/**
 * `supabase-project` — ProjectResourceKind, spec §5.1 / §5.3.
 *
 * A single Supabase Cloud project owned by a `supabase-org-admin`.
 * The Access bundle is the largest one in the v1 catalogue: the
 * project's REST URL, anon key, service_role key, DB password and
 * project ref. All five are issued and rotated by the managing
 * `supabase-org-admin` via the Supabase Management API.
 *
 * Rotation is `admin-mediated` (spec §0.1): the project's
 * service_role key and DB password are regenerated by the managing
 * admin, not by the user. The CRM "Rotate Access" flow detects this
 * and routes the request through the parent admin Resource (Phase 6).
 *
 * No `mcpFragment` for this kind — the Supabase MCP is account/PAT
 * driven (cf. `supabase-org`), not service-role driven. Wiring MCP at
 * the project level would require a different server image that
 * doesn't exist in the official ecosystem today.
 */

import type { ResourceKind } from '../../resource-kind.js';

interface SupabaseProjectMetadata {
  readonly orgSlug: string;
  readonly projectRef: string;
  /** Cloud region of the project (e.g. `eu-west-3`). Informational. */
  readonly region?: string;
}

function isSupabaseProjectMetadata(value: unknown): value is SupabaseProjectMetadata {
  if (typeof value !== 'object' || value === null) return false;
  const v = value as {
    orgSlug?: unknown;
    projectRef?: unknown;
    region?: unknown;
  };
  return (
    typeof v.orgSlug === 'string' &&
    v.orgSlug.length > 0 &&
    typeof v.projectRef === 'string' &&
    v.projectRef.length > 0 &&
    (v.region === undefined || typeof v.region === 'string')
  );
}

const SETUP_DOCS = `## \`supabase-project\` is admin-managed

You do **not** provision this Resource by pasting tokens. A
\`supabase-project\` is always created and rotated by its managing
\`supabase-org-admin\` Resource — see spec §0.1 (\`admin-mediated\`
rotation) and §5.3.

### How to add a supabase-project to the CRM

1. Make sure your organization already has a \`supabase-org-admin\`
   Resource registered. If not, follow the \`supabase-org-admin\`
   setup first.
2. Open the CRM "+ Add Resource" wizard, pick \`supabase-project\`,
   and select the managing admin from the dropdown.
3. Choose **Create new** (the admin provisions a fresh Supabase
   project via POST \`/v1/projects\`) or **Adopt existing** (the
   admin inventories an existing project and regenerates a fresh
   service_role key + DB password to ensure key custody is with the
   CRM).
4. The CRM seals the resulting bundle client-side (spec §4) under
   keys \`SUPABASE_URL\`, \`SUPABASE_ANON_KEY\`,
   \`SUPABASE_SERVICE_ROLE_KEY\`, \`SUPABASE_DB_PASSWORD\`, and
   \`SUPABASE_PROJECT_REF\`. Cleartext never reaches the server.

### What these credentials can do

- \`SUPABASE_URL\`: the project's REST/Realtime URL
  (\`https://<ref>.supabase.co\`). Not strictly secret but bundled
  for convenience.
- \`SUPABASE_ANON_KEY\`: public, browser-safe JWT (anonymous role).
  Required by the client SDK. Stored in the sealed bundle for
  uniformity even though it's labeled "public" by Supabase.
- \`SUPABASE_SERVICE_ROLE_KEY\`: privileged JWT (full DB access via
  PostgREST, bypasses RLS). **Treat as root credentials.** Rotated
  by the managing admin via POST \`/v1/projects/{ref}/api-keys\`.
- \`SUPABASE_DB_PASSWORD\`: Postgres role password (\`postgres\`).
  Used by direct \`psql\` / pooler connections. Rotated by the
  managing admin via POST \`/v1/projects/{ref}/database/password\`.
- \`SUPABASE_PROJECT_REF\`: stable project identifier
  (\`[a-z]{20}\`). Used in every Management API URL. Not a secret.

### Rotation

Open the CRM resource page → "Rotate Access". The request is
dispatched to the managing \`supabase-org-admin\`, which calls the
appropriate Management API endpoint per key:

- \`SUPABASE_SERVICE_ROLE_KEY\` → POST
  \`/v1/projects/{ref}/api-keys\` with \`{ type: 'service_role' }\`.
- \`SUPABASE_DB_PASSWORD\` → POST
  \`/v1/projects/{ref}/database/password\`.
- \`SUPABASE_ANON_KEY\` → rotated together with the service_role key
  on the same API call.

The new values are sealed for the same recipient set; the old keys
are revoked within seconds.

### What if my managing admin is detached?

A \`supabase-project\` with no live \`admin_resource_id\` link (spec
§3.3) cannot be rotated. The CRM surfaces a 409 with
\`rotationMethod=admin-mediated\` and a "Re-attach an admin" CTA.
Re-attach by editing the Resource and picking another live
\`supabase-org-admin\` from the same organization.
`;

export const supabaseProject: ResourceKind = {
  id: 'supabase-project',
  provider: 'supabase-cloud',
  kindClass: 'project',
  displayName: 'Supabase project',
  setupDocs: SETUP_DOCS,
  accessSchema: {
    SUPABASE_URL: {
      label: 'Supabase project URL',
      description:
        'REST / Realtime / Storage / Auth URL of the project ' +
        '(`https://<ref>.supabase.co`). Issued by the managing ' +
        '`supabase-org-admin`; you do not paste it manually.',
      required: true,
      pattern: '^https://[a-z]{20}\\.supabase\\.co$',
    },
    SUPABASE_ANON_KEY: {
      label: 'Supabase anon key (public JWT)',
      description:
        'Anonymous-role JWT used by the client SDK. Labelled "public" by ' +
        'Supabase but bundled here for uniformity. Rotates with the ' +
        'service_role key.',
      required: true,
      pattern: '^eyJ[A-Za-z0-9_\\-]+\\.eyJ[A-Za-z0-9_\\-]+\\.[A-Za-z0-9_\\-]+$',
    },
    SUPABASE_SERVICE_ROLE_KEY: {
      label: 'Supabase service_role key (privileged JWT)',
      description:
        'Service-role JWT — bypasses RLS, full read/write on every table. ' +
        'Treat as root credentials. Issued and rotated by the managing ' +
        '`supabase-org-admin`.',
      required: true,
      pattern: '^eyJ[A-Za-z0-9_\\-]+\\.eyJ[A-Za-z0-9_\\-]+\\.[A-Za-z0-9_\\-]+$',
    },
    SUPABASE_DB_PASSWORD: {
      label: 'Supabase Postgres password',
      description:
        'Password of the `postgres` role on the project DB. Used by direct ' +
        '`psql` / pooler / Supabase CLI db connections. Rotated by the ' +
        'managing admin via the Management API.',
      required: true,
    },
    SUPABASE_PROJECT_REF: {
      label: 'Supabase project ref',
      description:
        'Stable project identifier (20 lowercase letters). Used in every ' +
        'Management API URL. Not a secret but bundled for convenience.',
      required: true,
      pattern: '^[a-z]{20}$',
    },
  },
  metadataSchema: {
    description:
      'SupabaseProjectMetadata: { orgSlug: string, projectRef: string, region?: string }',
    fields: {
      orgSlug: { type: 'string', required: true },
      projectRef: { type: 'string', required: true },
      region: { type: 'string', required: false },
    },
  },
  rotationMethod: 'admin-mediated',
  healthTestCmd(metadata, _access): string {
    if (!isSupabaseProjectMetadata(metadata)) {
      throw new Error(
        'supabase-project: invalid metadata, expected { orgSlug, projectRef, region? }',
      );
    }
    // Use the anon key against the project REST root — passes iff the
    // URL is reachable and the anon key is valid. Service_role health
    // would leak more capability than we want a passive healthcheck to
    // require.
    return (
      `curl -fsS -H "apikey: $SUPABASE_ANON_KEY" ` +
      `-H "Authorization: Bearer $SUPABASE_ANON_KEY" ` +
      `"$SUPABASE_URL/rest/v1/?select=*" >/dev/null`
    );
  },
  egressHosts(metadata): readonly string[] {
    if (!isSupabaseProjectMetadata(metadata)) {
      // Defensive fallback — never reachable if validation runs upstream.
      return ['api.supabase.com', 'supabase.co'];
    }
    return [
      'api.supabase.com',
      `${metadata.projectRef}.supabase.co`,
      // Pooler host varies by region; we list the wildcard parent zone
      // so the mitmproxy egress allowlist matches any pooler subdomain.
      'pooler.supabase.com',
    ];
  },
};
